log(`Strictly verifying ${TASKS.length} candidate pairs`)

function buildPrompt(t) {
  return `Two excerpts below come from two different reviewers of the SAME paper. Decide whether they raise the SAME SPECIFIC issue — i.e., they are near-paraphrases of the same concrete complaint about the same aspect of the paper, such that a third reader would say "these two reviewers made the same point."

Be STRICT. Return same_issue=0 if:
- they are merely about the same general topic (e.g. both about experiments, novelty, or clarity) but complain about different specifics
- one is a specific complaint and the other is a generic/vague statement
- one subsumes the other only loosely, or they only partially overlap
- one is a question and the other is a criticism that only shares the topic

Return same_issue=1 ONLY if the two excerpts make the same specific point.

=== EXCERPT 1 ===
${t.text1}
=== EXCERPT 2 ===
${t.text2}

Return your verdict via the required structured output only, with a one-sentence reason.`
}

const CONCURRENCY = 5
const results = []
for (let i = 0; i < TASKS.length; i += CONCURRENCY) {
  const chunk = TASKS.slice(i, i + CONCURRENCY)
  const chunkResults = await parallel(chunk.map((t) => async () => {
    const out = await agent(buildPrompt(t), {
      label: `pair${t.pair_id}`,
      schema: SCHEMA,
      model: 'sonnet',
    })
    if (!out) return null
    return { pair_id: t.pair_id, same_issue: out.same_issue, reason: out.reason }
  }))
  results.push(...chunkResults)
  if ((i / CONCURRENCY) % 20 === 0) log(`chunk ${i / CONCURRENCY + 1}/${Math.ceil(TASKS.length / CONCURRENCY)}`)
}

const flat = results.filter(Boolean)
log(`${flat.length} verified, ${flat.filter((r) => r.same_issue === 1).length} strict matches`)
return flat
